<!-- CommentSection.vue -->
<template>
  <div>
    <!-- Кнопка для загрузки комментариев -->
    <!-- @click - обработчик клика -->
    <!-- :disabled - отключение кнопки во время загрузки -->
    <button 
    class="btn primary" @click="loadComments" :disabled="isLoading"
    v-if="comments.length === 0 && !isLoading">
      <!-- Динамический текст кнопки в зависимости от состояния загрузки -->
      {{ isLoading ? "Загрузка..." : "Загрузить комментарии" }}
    </button>

    <!-- Индикатор загрузки -->
    <!-- v-if - отображается только при активной загрузке -->
    <div v-if="isLoading" class="loader"></div>
    <div v-else-if="error" class="error">
      {{ error }}
    </div>
    <!-- Блок с комментариями -->
    <!-- v-else-if - отображается, если загрузка завершена и есть комментарии -->
    <div v-else-if="comments.length > 0">
      <h2>Комментарии к резюме</h2>

      <!-- Список комментариев -->
      <ul class="list">
        <!-- Итерация по массиву комментариев -->
        <!-- :key - уникальный идентификатор для оптимизации рендеринга -->
        <li v-for="comment in comments" :key="comment.id" class="list-item">
          <div>
            <!-- Отображение имени автора -->
            <p>От: {{ comment.email }}</p>
            <!-- Тело комментария -->
            <small>{{ comment.body }}</small>
          </div>
        </li>
      </ul>
    </div>
  </div>
</template>

<script>
export default {
  // Локальное состояние компонента
  data() {
    return {
      comments: [], // Массив для хранения загруженных комментариев
      isLoading: false, // Флаг состояния загрузки
      error: null,
    };
  },
  methods: {
    // Асинхронный метод загрузки комментариев
    async loadComments() {
      this.isLoading = true; // Активируем состояние загрузки
      this.error = null;
      try {
        // Выполняем GET-запрос к API
        const response = await fetch(
          "https://jsonplaceholder.typicode.com/comments?_limit=42"
        );

        // Проверка статуса ответа
        if (!response.ok) {
          throw new Error(`HTTP error! Status: ${response.status}`);
        }

        const data = await response.json();

        // Проверка структуры ответа
        if (
          !Array.isArray(data) ||
          !data.every(
            (item) => "id" in item && "email" in item && "body" in item
          )
        ) {
          throw new Error("Некорректный формат комментариев");
        }

        this.comments = data;
      } catch (error) {
        // Обработка ошибок при загрузке
        this.error = `Ошибка загрузки: ${error.message}`;
        console.error("Ошибка:", error);
      } finally {
        // Выключаем состояние загрузки в любом случае
        this.isLoading = false;
      }
    },
  },
};
</script>

<style scoped>
h2 {
  color: #fff;
}
/* Стили только для этого компонента */
.loader {
  border: 4px solid #f3f3f3; /* Светлая рамка */
  border-top: 4px solid #3498db; /* Синяя верхняя рамка для анимации */
  border-radius: 50%; /* Круглая форма */
  width: 20px; /* Размеры */
  height: 20px;
  animation: spin 1s linear infinite; /* Анимация вращения */
  margin: 10px auto; /* Центрирование */
}
.error {
  color: red;
  margin: 10px 0;
}
/* Анимация вращения */
@keyframes spin {
  0% {
    transform: rotate(0deg); /* Начальное положение */
  }
  100% {
    transform: rotate(360deg); /* Полный оборот */
  }
}

.list {
  list-style: none; /* Убираем маркеры списка */
  padding: 0; /* Убираем отступы */
}

.list-item {
  color: #fff;
  margin: 15px 0;
  padding: 10px;
  border: 1px solid #eee;
  border-radius: 4px;
}

.list-item p {
  margin: 5px 0;
}

.list-item small {
  display: block;
  margin-top: 5px;
}
</style>
