<!-- ConstructorPanel.vue форма добавления -->
<template>
    <form class="card">
        <!-- Выбор типа блока -->
      <div class="form-control">
        <label for="type">Тип блока</label>
         <!-- Привязка выбранного значения к selectedType -->
        <select id="type" v-model="selectedType">
          <option value="title">Заголовок</option>
          <option value="subtitle">Подзаголовок</option>
          <option value="avatar">Аватар (URL)</option>
          <option value="text">Текст</option>
        </select>
      </div>
  <!-- Поле ввода значения -->
      <div class="form-control">
        <label for="value">Значение</label>
         <!-- Двусторонняя привязка текста к inputValue -->
        <textarea id="value" rows="3" v-model="inputValue"></textarea>
      </div>
  <!-- Кнопка добавления -->
      <button class="btn primary" :disabled="!isButtonEnabled" @click.prevent="addBlock">
        Добавить
      </button>
      <!-- // Отключаем кнопку при невалидной форме -->
      <!-- // Обработчик клика с предотвращением отправки формы  -->
    </form>
  </template>
  
  <script>
  export default {
    data() {
      return {
        selectedType: 'title', // Текущий выбранный тип блока
        inputValue: '', // Введенное пользователем значение
      };
    },
    computed: {
        // Проверка валидности формы
      isButtonEnabled() {
        return this.inputValue.trim().length > 3;
      },
    },
    methods: {
      addBlock() {
        // Создаем объект нового блока
        const block = {
          type: this.selectedType,
          value: this.inputValue.trim(), // Удаляем пробелы в начале/конце
        };
        // Отправляем событие с новым блоком родителю
        this.$emit('add-block', block);
        this.inputValue = ''; // Очистка поля ввода
      },
    },
  };
  </script>
  
  <style scoped>
  .card {
    padding: 20px;
    border: 1px solid #ccc;
    border-radius: 8px;
  }
  .form-control {
    margin-bottom: 15px;
  }
  .form-control select{
    padding: 0.5rem;
  }
  .btn {
    padding: 10px 15px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
  }
  .primary {
    background-color: #007bff;
    color: white;
  }
  .primary:disabled {
    background-color: #ccc;
  }
  </style>