<!-- src/App.vue -->
<template>
  <h1>Приложение для создания электронного резюме</h1>
  <!-- Основной контейнер с вертикальным расположением -->
  <div class="container column">
    <!-- Компонент формы для добавления блоков -->
    <!-- @add-block - обработчик события добавления нового блока -->
    <ConstructorPanel @add-block="addBlock" />
    
    <!-- Компонент отображения резюме -->
    <!-- :blocks - передача массива блоков через props -->
    <ResumeBlock :blocks="blocks" />
  </div>

  <!-- Контейнер для секции комментариев -->
  <div class="container">
    <!-- Компонент комментариев -->
    <CommentSection />
  </div>
</template>

<script>
// Импорт дочерних компонентов
import ConstructorPanel from './components/ConstructorPanel.vue'; // Форма создания блоков
import ResumeBlock from './components/ResumeBlock.vue';           // Отображение резюме
import CommentSection from './components/CommentSection.vue';    // Секция комментариев

export default {
  // Регистрация компонентов
  components: { 
    ConstructorPanel, // Компонент формы ввода
    ResumeBlock,      // Компонент резюме
    CommentSection    // Компонент комментариев
  },
  
  // Локальное состояние компонента
  data() {
    return {
      blocks: [], // Хранит массив блоков резюме
    };
  },

  // Методы компонента
  methods: {
    // Добавление нового блока в массив
    addBlock(block) {
      this.blocks.push(block); // Добавляет переданный блок в конец массива
    },
  },
};
</script>

