<!-- ResumeBlock.vue -->
<template>
  <!-- Основной контейнер компонента -->
  <div class="card">
    <!-- Условный рендеринг при отсутствии блоков -->
    <div v-if="blocks.length === 0">
      <!-- Сообщение-заглушка -->
      <h3>Добавьте первый блок резюме, чтобы увидеть результат</h3>
    </div>
    
    <!-- Рендеринг при наличии блоков -->
    <div v-else>
      <!-- Динамический компонент -->
      <component
        v-for="(block, index) in blocks"  
        :key="index"  
        :is="getComponentName(block.type)"  
        :value="block.value"  
      />
    </div>
    <!-- // Итерация по массиву блоков
    // Уникальный ключ для оптимизации рендеринга
    // Динамическое определение компонента
    // Передача данных в дочерний компонент -->
  </div>
</template>

<script>
// Импорт дочерних компонентов
import TitleBlock from '../blocks/TitleBlock.vue';
import SubtitleBlock from '../blocks/SubtitleBlock.vue';
import AvatarBlock from '../blocks/AvatarBlock.vue';
import TextBlock from '../blocks/TextBlock.vue';

export default {
  // Получение данных от родительского компонента
  props: {
      blocks: {  // Массив блоков для отображения
          type: Array,
          required: true,  // Обязательное свойство
      },
  },
  
  methods: {
      // Определение компонента по типу блока
      getComponentName(type) {
          switch (type) {  // Сопоставление типа с компонентом
              case 'title': return 'TitleBlock';
              case 'subtitle': return 'SubtitleBlock';
              case 'avatar': return 'AvatarBlock';
              case 'text': return 'TextBlock';
              default: return null;  // Запасной вариант
          }
      },
  },
  
  // Локальная регистрация компонентов
  components: {
      TitleBlock,  // Компонент заголовка
      SubtitleBlock,  // Компонент подзаголовка
      AvatarBlock,  // Компонент аватара
      TextBlock,  // Текстовый компонент
  },
};
</script>

<!-- Стили с ограниченной областью видимости -->
<style scoped>
.card {
  padding: 20px;
  border: 1px solid #ccc;  
  border-radius: 8px;  
}
</style>