<template>
  <!-- Компонент для отображения подзаголовка третьего уровня -->
  <h3>{{ value }}</h3> <!-- Вывод переданного текстового содержимого -->
</template>

<script>
export default {
  // Интерфейс компонента: входные параметры
  props: {
      value: {  // Основное свойство компонента
          type: String,  // Строковый тип данных
          required: true,  // Параметр обязателен для передачи
      },
  },
  // Компонент не содержит:
  // - Локальных данных (data)
  // - Методов (methods)
  // - Хуков жизненного цикла
};
</script>

<!-- 
Особенности реализации:
1. Простой презентационный компонент
2. Получает данные исключительно через props
3. Не имеет внутреннего состояния
4. Используется для семантической разметки контента
5. Стили могут применяться через глобальные CSS или родительские компоненты
-->