<template>
  <!-- Компонент для отображения заголовка -->
  <h2>{{ value }}</h2> <!-- Вывод значения из props -->
</template>

<script>
export default {
  // Определение входных параметров компонента
  props: {
      value: {  // Основное текстовое содержимое
          type: String,  // Ожидается строка
          required: true,  // Обязательный параметр
      },
  },
  // Компонент не имеет собственного состояния (data)
  // и методов, только отображает полученные данные
};
</script>

<!-- 
Особенности компонента:
1. Stateless - не хранит собственных данных
2. Полностью управляется через props
3. Выполняет единственную задачу: рендеринг текста в теге h2
4. Не содержит стилей (может наследовать от родителя)
-->