<!-- AvatarBlock.vue -->
<template>
  <!-- Контейнер для аватара с CSS-классом для стилизации -->
  <div class="avatar">
    <!-- Изображение с динамическим источником -->
    <img 
      :src="value"       
      alt="Avatar"       
      @error="handleImageError" 
    >
  </div>
<!-- Привязка src к значению из пропса -->
 <!-- Альтернативный текст для доступности -->
  <!-- Обработчик ошибок загрузки изображения -->
</template>

<script>
export default {
  // Объявление входных параметров
  props: {
    value: {  // Основное свойство для URL изображения
      type: String,       // Ожидаемый тип данных
      required: true,     // Обязательный параметр
      validator: value => {  // Кастомная валидация
        // Проверка Data URL (base64)
        if (value.startsWith('data:image')) return true;
        
        // Проверка абсолютных URL
        try {
          new URL(value);  // Нативная проверка URL
          return true;
        } catch {
          /* Проверка относительных путей:
             - Начинаются с / (например: "/images/avatar.png")
             - Следующий символ не должен быть / (исключаем "//site.com") */
          return /^\/[^/]/.test(value);
        }
      }
    },
  },
  data() {
    return {
      imageSrc: this.value, // Первоначальный источник
      errorCount: 0 // Счетчик ошибок
    }
  },
  // Методы компонента
  methods: {
    // Обработчик ошибок загрузки изображения
    handleImageError(e) {
      if(this.errorCount >= 1) {
        // Если уже была одна ошибка, прекращаем попытки
        e.target.style.display = 'none';
        return;
      }
      
      // Пробуем загрузить дефолтное изображение
      this.imageSrc = process.env.BASE_URL + 'default-avatar.jpeg';
      this.errorCount++;
      
      // Форсируем обновление атрибута src
      this.$nextTick(() => {
        e.target.src = this.imageSrc;
      });
    }
  }
};
</script>

<!-- Стили с ограниченной областью видимости -->
<style scoped>
.avatar {
  display: flex;       /* Flex-контейнер для центрирования */
  justify-content: center; /* Горизонтальное центрирование */
}
.avatar img {
  width: 150px;       /* Фиксированная ширина */
  height: auto;       /* Сохранение пропорций */
  border-radius: 50%; /* Скругление для круглой формы */
}
</style>