<template>
  <!-- Базовый компонент для текстового контента -->
  <p>{{ value }}</p> <!-- Отображение строки из входного параметра -->
</template>

<script>
export default {
  // Определение принимаемых параметров
  props: {
      value: {  // Основное текстовое содержимое
          type: String,  // Строковый тип данных
          required: true,  // Обязательное требование для работы
      },
  },
  // Компонент не содержит:
  // - Локального состояния (data)
  // - Методов (methods)
  // - Вычисляемых свойств (computed)
};
</script>

<!-- 
Особенности реализации:
1. Минималистичный компонент-представление
2. Полностью управляется через props
3. Не имеет собственной логики отображения
4. Повторно используется для любых текстовых блоков
5. Стилизация выполняется через родительские компоненты
-->